const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-70.647985, -34.752733]);
  const basin = point.buffer(10000); // 10 km buffer around the point

  const date2021 = '2021-12-18';
  const date2023 = '2023-12-18';
  const startOffset = 1; // days to extend if no image found
  const endOffset = 1;

  // Function to get Sentinel-2 image for a given date
  function getImage(targetDate) {
    let start = ee.Date(targetDate).advance(-startOffset, 'day');
    let end = ee.Date(targetDate).advance(endOffset, 'day');
    // Sentinel-2 Level-2A
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(basin)
      .filterDate(start, end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Pre-filter cloudy images

    let image = collection.mosaic().clip(basin); // Mosaic if multiple images
    return { image: image, collection: collection, date: targetDate };
  }

  // Function to process an image and compute snow area
  function processImage(imgObj) {
    let image = imgObj.image;
    // Cloud masking from QA60 (bits 10 and 11 are clouds and cirrus)
    let qa = image.select('QA60');
    let cloudBitMask = (1 << 10) | (1 << 11);
    let mask = qa.bitwiseAnd(cloudBitMask).eq(0);
    image = image.updateMask(mask);

    // Compute NDSI using B3 (Green) and B11 (SWIR)
    let ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    // Snow mask: NDSI > 0.4 (common threshold)
    let snow = ndsi.gt(0.4).rename('snow');

    // Count total valid pixels (after cloud masking) in the region
    let validCount = snow.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: basin,
      scale: 20, // Sentinel-2 resolution for NDSI (using B11 at 20m)
      maxPixels: 1e9
    }).get('snow').getInfo(); // This counts all pixels (snow and non-snow) because snow is binary (0 or 1)

    // If validCount is 0, then no valid pixels after masking
    if (validCount === 0) {
      return { snowArea: 0, validCount: 0, error: 'C2' };
    }

    // Compute snow area (in square meters) by counting snow pixels and multiplying by pixel area (20m * 20m = 400 m²)
    let snowCount = snow.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: basin,
      scale: 20,
      maxPixels: 1e9
    }).get('snow').getInfo();

    let snowArea = snowCount * 20 * 20; // each pixel is 20m x 20m
    return { snowArea: snowArea, validCount: validCount, error: null };
  }

  // Get images for both dates
  let img2021 = getImage(date2021);
  let img2023 = getImage(date2023);

  // Check if collections are empty
  let size2021 = img2021.collection.size().getInfo();
  let size2023 = img2023.collection.size().getInfo();

  console.log(`2021-12-18 Images: ${size2021}`);
  console.log(`2023-12-18 Images: ${size2023}`);

  // If no images for either date, try to extend date range to ±3 days? But we already used ±1 day.
  // If still 0, output C1.
  if (size2021 === 0 || size2023 === 0) {
    console.log("No images found for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Process images
  let result2021 = processImage(img2021);
  let result2023 = processImage(img2023);

  // Check for C2 (no valid pixels)
  if (result2021.error === 'C2' || result2023.error === 'C2') {
    console.log("No valid pixels after cloud masking for one or both dates.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid results (NaN, null, or unreasonable values)
  // Snow area should be >=0 and less than area of basin (approx. pi * 10000^2 = 3.14e8 m²)
  let basinArea = Math.PI * 10000 * 10000;
  if (isNaN(result2021.snowArea) || isNaN(result2023.snowArea) ||
      result2021.snowArea === null || result2023.snowArea === null ||
      result2021.snowArea < 0 || result2023.snowArea < 0 ||
      result2021.snowArea > basinArea || result2023.snowArea > basinArea) {
    console.log("Invalid snow area calculated.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`2021 Snow Area: ${result2021.snowArea.toFixed(0)} m², Valid Pixels: ${result2021.validCount}`);
  console.log(`2023 Snow Area: ${result2023.snowArea.toFixed(0)} m², Valid Pixels: ${result2023.validCount}`);

  // Compare snow areas
  if (result2023.snowArea > result2021.snowArea) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
